// Receipt-driven presentation refreshes. Low-level reads still invalidate at
// every confirmed write; unknown/compound events retain the full refresh.
import { Interface } from 'ethers';
import { CONTRACTS } from './chain-config.js';
import { hasSchema, loadSchema } from '../chain/generated/index.js';

const effects = new Map();
function register(contract, names, domains) {
  for (const name of names.split(' ')) effects.set(contract + ':' + name, domains.split(' '));
}
register('COINFLIP', 'CoinflipDeposit CoinflipStakeUpdated CoinflipClaimState CoinflipAutoRebuyToggled CoinflipAutoRebuyStopSet', 'coinflip balances claims activity');
register('COINFLIP', 'BigRecordUpdated', 'coinflip balances claims activity records sdgnrs');
register('COINFLIP', 'BafDrawEntered', 'coinflip balances claims activity baf');
register('COINFLIP', 'QuestCompleted', 'quests activity coinflip balances claims');
register('QUESTS', 'QuestProgressUpdated QuestCompleted QuestStreakShieldUsed QuestStreakShieldGranted QuestStreakBonusAwarded QuestStreakReset GrowthBetQuestCompleted LevelQuestCompleted', 'quests activity coinflip balances claims');
register('AFFILIATE', 'Affiliate ReferralUpdated AffiliateEarningsRecorded AffiliateTopUpdated', 'affiliate balances claims coinflip');
register('GAME', 'OperatorApproval', 'permissions balances');
register('GAME', 'WinningsClaimed PlayerCredited ClaimableSpent', 'claims balances passes');
// Starting AFKing updates the quest run without necessarily emitting Quest*.
register('GAME', 'AfkingFunded AfkingWithdrew AfkingSpent AfkingStethFunded SubscriptionUpdated SubscriptionPaused SubscriptionExpired', 'passes balances claims quests activity');
register('GAME', 'AfkingFlipClaimed AffiliateBaseDrained', 'passes balances claims coinflip affiliate');
register('AFKING_SUB_TOKEN', 'Transfer SeatMinted VaultSeatsMinted SeatRestyled', 'passes balances');
register('AFKING_SUB_TOKEN', 'Approval ApprovalForAll', 'passes permissions balances');
register('COIN', 'Transfer', 'balances coinflip claims sdgnrs');
register('COIN', 'Approval', 'permissions balances');
register('DGNRS', 'Transfer', 'sdgnrs balances claims');
register('SDGNRS', 'Transfer', 'sdgnrs balances claims');
register('DGNRS', 'Approval', 'permissions balances');
register('WWXRP', 'Transfer PrizeCredited PrizeWithdrawn PrizeConsumed DrawEntered DrawClaimed', 'wwxrp balances claims');
register('WWXRP', 'Approval', 'permissions balances');

const interfaces = new Map();
function ifaceFor(contract) {
  if (!interfaces.has(contract)) {
    const pending = loadSchema(contract).then(({ abi }) => new Interface(abi)).catch(error => {
      interfaces.delete(contract);
      throw error;
    });
    interfaces.set(contract, pending);
  }
  return interfaces.get(contract);
}

/** No RPC: decode complete receipts against the emitting deployment's ABI. */
export async function classifyReceiptEffects(receipt) {
  if (!Array.isArray(receipt?.logs) || receipt.logs.length === 0) return null;
  const contracts = new Map();
  for (const [name, address] of Object.entries(CONTRACTS)) {
    if (!hasSchema(name)) continue;
    const key = String(address).toLowerCase();
    if (!contracts.has(key)) contracts.set(key, []);
    contracts.get(key).push(name);
  }
  const changed = new Set();
  try {
    for (const log of receipt.logs) {
      const hosts = contracts.get(String(log?.address).toLowerCase());
      if (!hosts || log?.removed || !Array.isArray(log?.topics) || !log.topics.length
        || typeof log?.data !== 'string') return null;
      let recognized = false;
      // Some deployments share the Coinflip/Quests/Affiliate host address.
      // Decode all matching schemas rather than letting an alias hide events.
      for (const host of hosts) {
        const iface = await ifaceFor(host);
        if (!iface.getEvent(log.topics[0])) continue;
        const parsed = iface.parseLog(log);
        if (!parsed) return null;
        // Force deferred ABI decoding errors before treating a log as known.
        parsed.args.toArray(true);
        const domains = effects.get(host + ':' + parsed.name);
        if (!domains) return null;
        domains.forEach(domain => changed.add(domain));
        recognized = true;
      }
      if (!recognized) return null;
    }
  } catch (_) { return null; }
  return [...changed].sort();
}

/** Missing metadata or an unclassified consumer keeps the broad fallback. */
export function transactionAffects(changed, domains) {
  return !Array.isArray(changed) || !changed.every(value => typeof value === 'string')
    || !Array.isArray(domains) || domains.some(domain => changed.includes(domain));
}

/** Unknown cache keys remain conservative as new display caches are added. */
export function displaySnapshotDomains(key) {
  if (key.startsWith('ticket:') || key.startsWith('ticket-view:')) return ['tickets'];
  if (key.startsWith('afking:')) return ['passes'];
  if (key === 'deity-catalog') return ['deities'];
  if (key.startsWith('token-')) return ['balances'];
  if (key === 'last-completed-draw') return ['jackpots'];
  if (key === 'game-day' || key === 'game-context') return [];
  return null;
}
